// Removed-names check: a bipe-shared pull request must not remove a generated name (a string key, a
// Swift or Kotlin declaration) that hand-written code on bipe-app main still uses.
// Why: after such a pull request merges, every regen branch is cut from bipe-app main and gets the new
// generated files, so each one fails to compile until the bipe-app pull request that drops the use
// merges. bipe-shared#345 removed bipe_chat_list_more before bipe-app#351 merged, and the iOS, Android
// and captures jobs of bipe-app#354, #358 and #359 failed on it (2 Nov 2026).
// Rule: to add a name, merge bipe-shared first. To remove a name, merge the bipe-app pull request first.
// Usage: node tools/check-removed.mjs --main <bipe-app on main> --branch <bipe-app on the PR branch>
// Both are git checkouts; the check reads their committed HEAD. Exit 1 when main still uses a removed name.
import { execFileSync } from "node:child_process";
import { existsSync } from "node:fs";
import { resolve } from "node:path";

const args = process.argv.slice(2);
const option = (flag) => (args.includes(flag) ? resolve(args[args.indexOf(flag) + 1]) : null);
const mainDir = option("--main");
const branchDir = option("--branch");
if (!mainDir || !branchDir) throw new Error("usage: node tools/check-removed.mjs --main <dir> --branch <dir>");

// The folders that regen writes in bipe-app (checks.yml, generated()), plus the store captures.
const GENERATED_DIRS = [
  "ios/BipeKit/Sources/BipeKit/Generated",
  "ios/BipeKit/Sources/BipeKit/Resources",
  "android/libraries/bipe/src/main",
  "android/app/src/screenshotTest/kotlin/chat/bipe/app/store/generated",
  "core/crates/bipe-core/src/generated",
];
const SOURCE = /\.(swift|kt|kts|xml|rs)$/;
const MARK = "Generated by bipe-shared";

const git = (dir, ...a) => execFileSync("git", ["-C", dir, ...a], { encoding: "utf8", maxBuffer: 1 << 28 });

function files(dir) {
  const out = git(dir, "ls-files", "-z", "--", "ios", "android", "core/crates");
  return out.split("\0").filter((p) => SOURCE.test(p) || p.endsWith(".strings"));
}

function read(dir, path) {
  return git(dir, "show", `HEAD:${path}`);
}

function isGenerated(path, text) {
  return GENERATED_DIRS.some((d) => path.startsWith(`${d}/`)) && text.includes(MARK);
}

// Names a generated file declares. Swift and Kotlin declarations, Android resource names, .strings keys.
function declared(path, text) {
  const names = new Set();
  const patterns = path.endsWith(".swift")
    ? [/\b(?:let|var|func|case|struct|enum|class|typealias|protocol)\s+`?([A-Za-z_]\w*)/g]
    : path.endsWith(".kt") || path.endsWith(".kts")
      ? [/\b(?:val|var|fun|object|class|interface|typealias)\s+`?([A-Za-z_]\w*)/g]
      : path.endsWith(".rs")
        ? [/\b(?:const|static|fn|struct|enum|type|mod|trait|let(?:\s+mut)?)\s+([A-Za-z_]\w*)/g]
      : path.endsWith(".xml")
        ? [/\bname="([A-Za-z_]\w*)"/g]
        : [/^"([A-Za-z_]\w*)"\s*=/gm];
  for (const re of patterns) for (const m of text.matchAll(re)) names.add(m[1]);
  return names;
}

function scan(dir) {
  const generated = new Map();
  const handWritten = new Map();
  for (const path of files(dir)) {
    const text = read(dir, path);
    (isGenerated(path, text) ? generated : handWritten).set(path, text);
  }
  return { generated, handWritten };
}

for (const dir of [mainDir, branchDir]) if (!existsSync(dir)) throw new Error(`${dir} not found`);

const main = scan(mainDir);
const branch = scan(branchDir);
const before = new Set();
for (const [path, text] of main.generated) for (const n of declared(path, text)) before.add(n);
const after = new Set();
for (const [path, text] of branch.generated) for (const n of declared(path, text)) after.add(n);
// Short names (id, url) collide with unrelated code; a name the hand-written code declares is not ours.
const handDeclared = new Set();
for (const [path, text] of main.handWritten) for (const n of declared(path, text)) handDeclared.add(n);
const removed = new Set([...before].filter((n) => !after.has(n) && n.length >= 4 && !handDeclared.has(n)));

const uses = new Map();
for (const [path, text] of main.handWritten) {
  const lines = text.split("\n");
  lines.forEach((line, i) => {
    // A word in a comment is no use of a name: skip comment lines and the part after "//".
    const trimmed = line.trimStart();
    if (/^(\/\/|\/\*|\*)/.test(trimmed)) return;
    const code = line.replace(/\s\/\/.*$/, "");
    for (const m of code.matchAll(/[A-Za-z_]\w*/g)) {
      if (!removed.has(m[0])) continue;
      if (!uses.has(m[0])) uses.set(m[0], []);
      uses.get(m[0]).push(`${path}:${i + 1}`);
    }
  });
}

if (uses.size) {
  const list = [...uses].map(([name, at]) => `${name} (${at.slice(0, 3).join(", ")}${at.length > 3 ? ", ..." : ""})`);
  console.error(
    `removed-names check failed (${uses.size}): this change removes names that bipe-app main still uses:\n- ${list.join("\n- ")}\n` +
      "Fix: merge the bipe-app pull request that drops the use first, then re-run this check. That is the bipe-app " +
      "pull request on this branch, or, when bipe-shared main already removed the name, the one on that change's branch. " +
      "If this change merges first, every bipe-app branch cut from main fails to compile until that pull request merges.",
  );
  process.exit(1);
}
console.log(`removed-names check ok (${removed.size} generated names removed, none used on bipe-app main)`);
